{"path":"outputs/t07_query.sparql","content":"PREFIX wd: <http://www.wikidata.org/entity/>
PREFIX wdt: <http://www.wikidata.org/prop/direct/>
PREFIX p: <http://www.wikidata.org/prop/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema: <http://schema.org/>
PREFIX skos: <http://www.w3.org/2004/02/skos/core#>

SELECT ?item ?itemLabel ?coordinates WHERE {
  ?item wdt:P31/wdt:P279* wd:Q41176 ;  # cultural institution (museum, gallery, library, etc.)
        wdt:P625 ?coordinates .
  FILTER NOT EXISTS { ?item wdt:P571 ?date . FILTER (?date > "1900-01-01"^^xsd:dateTime) }
  OPTIONAL {
    ?item p:P17 ps:P17 wd:Q29 .  # country is Spain
  }
  OPTIONAL {
    ?item wdt:P131 wd:Q11959 .  # located in Alicante
  }
  SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en" . }
}
LIMIT 100
"}

